// main.rs
use aws_sdk_sqs::Client;
use lambda_runtime::{run, service_fn, Error, LambdaEvent};
use serde_json::{json, Value};
use std::env;

#[tokio::main]
async fn main() -> Result<(), Error> {
    let config = aws_config::load_from_env().await;
    let sqs = Client::new(&config);
    run(service_fn(|event: LambdaEvent<Value>| handler(&sqs, event))).await
}

async fn handler(sqs: &Client, event: LambdaEvent<Value>) -> Result<Value, Error> {
    let queue_url = env::var("QUEUE_URL")?;
    let message = event.payload["message"].as_str().ok_or("missing message")?;
    sqs.send_message()
        .queue_url(&queue_url)
        .message_body(message)
        .send()
        .await?;
    Ok(json!({ "statusCode": 200, "body": "Message sent" }))
}
